-- Katalog metodik z kurikulum.aidetem.cz/vypis-vseho/ (49 metodik).
-- Stejné řádky, jaké by zapsalo tlačítko „Načíst katalog“ v Administraci.
-- Metodiky, které už v appce jsou (podle slugu), se nepřidají znovu.
on conflict (slug) where slug is not null do nothing;

select category, count(*) from public.modules group by category order by 1;
